<script>
    $(function () {
        $('.copy-bank').on('click', function () {
            const button = $(this);
            navigator.clipboard.writeText(button.data('copy')).then(function () {
                const original = button.html();
                button.html('<i class="bi bi-check2"></i> Copied');
                setTimeout(function () { button.html(original); }, 1500);
            });
        });
    });
</script>
